package vn.teaching.preparation;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import vn.teaching.exam.*;
import static vn.teaching.exam.ExamModels.*;
import vn.teaching.service.PlanningService;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class PreparationQuestionBankTest {
 @TempDir Path dir;PreparationStore store;PreparationQuestionBank bank;SourceService sources;ExamRepository repo;ExamAuth auth;String plan;
 @BeforeEach void setup()throws Exception{PlanningService planning=new PlanningService(dir,new Gson());plan=planning.saveOrUpdatePlanning(null,"Lesson","",null).getId();store=new PreparationStore(dir,new Gson(),planning);sources=mock(SourceService.class);repo=mock(ExamRepository.class);auth=mock(ExamAuth.class);when(auth.authenticate("token")).thenReturn(new Account("teacher","a@example.test","A","TEACHER"));bank=new PreparationQuestionBank(store,sources,repo,auth);}
 Question q(String id,String group,String status){return new Question(id,"source-1",1,"","","","","","","","","short","Question "+id,List.of(new Choice("A","Choice")),"SECRET_ANSWER",List.of(),"SECRET_SOLUTION",List.of(),group,status,"fp-"+id);}
 @Test void insertsCompleteGroupAndSeparatesAnswers()throws Exception{Question one=q("q1","g1","APPROVED"),two=q("q2","g1","APPROVED");when(sources.bank()).thenReturn(List.of(one,two));when(repo.all("questions",Question.class)).thenReturn(List.of(one,two));when(repo.require("question_groups","g1",Group.class)).thenReturn(new Group("g1","source-1","","Shared passage",List.of()));bank.insert(plan,"token",Map.of("questionId","q1","expectedRevision",0));JsonObject s=store.document(plan,"teacher").getAsJsonArray("sections").get(0).getAsJsonObject();assertTrue(PreparationStudentProjection.body(s).contains("Shared passage"));assertTrue(PreparationStudentProjection.body(s).contains("Question q2"));assertFalse(PreparationStudentProjection.body(s).contains("SECRET_ANSWER"));assertTrue(PreparationStudentProjection.teacherNotes(s).contains("SECRET_SOLUTION"));assertEquals(2,s.getAsJsonObject("questionBank").getAsJsonArray("questionIds").size());}
 @Test void refusesIncompleteGroup(){Question q=q("q1","g1","APPROVED");when(sources.bank()).thenReturn(List.of(q));when(repo.all("questions",Question.class)).thenReturn(List.of(q,q("q2","g1","NEEDS_REVIEW")));assertThrows(ExamException.class,()->bank.insert(plan,"token",Map.of("questionId","q1","expectedRevision",0)));assertEquals(0,store.document(plan,"teacher").get("revision").getAsInt());}
 @Test void rejectsStaleRevision(){assertThrows(ExamException.class,()->bank.insert(plan,"token",Map.of("questionId","q1","expectedRevision",9)));verifyNoInteractions(sources);}
 @Test void privateImageCannotBecomePublic()throws Exception{Path file=dir.resolve("image.png");Files.write(file,new byte[]{1});JsonObject a=store.register(plan,"teacher",file,"solution.png","image/png","question_private",0),doc=store.document(plan,"teacher"),s=new JsonObject();s.addProperty("id","s1");JsonObject snapshot=JsonParser.parseString("{\"sourceId\":\"source-1\",\"questionIds\":[\"q1\"],\"fingerprints\":[\"fp\"],\"images\":[{\"private\":false}]}").getAsJsonObject();snapshot.getAsJsonArray("images").get(0).getAsJsonObject().addProperty("imageAssetId",a.get("id").getAsString());s.add("questionBank",snapshot);doc.getAsJsonArray("sections").add(s);assertThrows(ExamException.class,()->PreparationQuestionSchema.validate(store,plan,"teacher",doc));}
 @Test void unknownPrivacyIsNotPublic(){JsonObject s=JsonParser.parseString("{\"questionBank\":{\"images\":[{\"imageAssetId\":\"a\"},{\"imageAssetId\":\"b\",\"private\":true},{\"imageAssetId\":\"c\",\"private\":false}]}}").getAsJsonObject();assertEquals(1,PreparationStudentProjection.publicQuestionImages(s).size());}

 JsonObject snapshotDocument(){JsonObject doc=store.document(plan,"teacher"),section=new JsonObject();section.addProperty("id","bank-section");section.addProperty("body","Student content");section.add("questionBank",JsonParser.parseString("{\"sourceId\":\"source-1\",\"questionIds\":[\"q1\"],\"fingerprints\":[\"fp\"],\"images\":[]}").getAsJsonObject());doc.getAsJsonArray("sections").add(section);return doc;}
 @Test void normalSaveCannotForgeQuestionProvenance(){JsonObject forged=snapshotDocument();assertThrows(ExamException.class,()->store.update(plan,"teacher",0,forged));assertEquals(0,store.document(plan,"teacher").get("revision").getAsInt());}
 @Test void normalSaveCannotModifyProvenanceButOmissionPreservesIt(){JsonObject original=snapshotDocument();store.update(plan,"teacher",0,original,true);JsonObject changed=store.document(plan,"teacher");changed.getAsJsonArray("sections").get(0).getAsJsonObject().getAsJsonObject("questionBank").addProperty("sourceId","fake-source");assertThrows(ExamException.class,()->store.update(plan,"teacher",1,changed));JsonObject omitted=store.document(plan,"teacher");JsonObject section=omitted.getAsJsonArray("sections").get(0).getAsJsonObject();section.remove("questionBank");section.addProperty("body","Teacher edited content");JsonObject saved=store.update(plan,"teacher",1,omitted);JsonObject savedSection=saved.getAsJsonArray("sections").get(0).getAsJsonObject();assertTrue(savedSection.has("questionBank"));assertEquals("source-1",savedSection.getAsJsonObject("questionBank").get("sourceId").getAsString());assertEquals("Teacher edited content",savedSection.get("body").getAsString());}
 @Test void restoreMayRecoverTrustedSnapshotAfterSectionRemoved(){store.update(plan,"teacher",0,snapshotDocument(),true);JsonObject removed=store.document(plan,"teacher");removed.add("sections",new JsonArray());store.update(plan,"teacher",1,removed);JsonObject restored=store.restore(plan,"teacher",1,2);assertEquals("source-1",restored.getAsJsonArray("sections").get(0).getAsJsonObject().getAsJsonObject("questionBank").get("sourceId").getAsString());}

 Question withAssets(List<String> assets){Question q=q("q-image","","APPROVED");return new Question(q.id(),q.sourceId(),q.sourcePage(),q.examType(),q.examVersion(),q.section(),q.subsection(),q.topic(),q.skill(),q.difficulty(),q.cognitiveLevel(),q.type(),q.stem(),q.choices(),q.answer(),q.acceptedAnswers(),q.solution(),assets,q.groupId(),q.status(),q.fingerprint());}
 void imageSource(String id,boolean valid)throws Exception{Path path=dir.resolve(id+".png");if(valid)javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",path.toFile());else Files.writeString(path,"corrupt image");when(sources.asset(id)).thenReturn(new Asset(id,"source-1",1,id+".png",0,0,2,2));when(sources.path(id+".png")).thenReturn(path);}
 Map<String,String> diskSnapshot()throws Exception{Map<String,String> result=new TreeMap<>();try(var paths=Files.walk(dir)){for(Path file:paths.filter(Files::isRegularFile).toList())result.put(dir.relativize(file).toString(),Base64.getEncoder().encodeToString(Files.readAllBytes(file)));}return result;}
 @Test void invalidSecondImageRollsBackAllCopiedFilesAndMetadata()throws Exception{imageSource("first",true);imageSource("second",false);when(sources.bank()).thenReturn(List.of(withAssets(List.of("first","second"))));JsonObject before=store.document(plan,"teacher");Map<String,String> disk=diskSnapshot();assertThrows(ExamException.class,()->bank.insert(plan,"token",Map.of("questionId","q-image","expectedRevision",0)));assertEquals(before,store.document(plan,"teacher"));assertEquals(disk,diskSnapshot());}
 @Test void sectionLimitFailureRollsBackImagesAndRevisionFiles()throws Exception{imageSource("first",true);when(sources.bank()).thenReturn(List.of(withAssets(List.of("first"))));JsonObject doc=store.document(plan,"teacher");for(int i=0;i<200;i++){JsonObject section=new JsonObject();section.addProperty("id","section-"+i);doc.getAsJsonArray("sections").add(section);}store.update(plan,"teacher",0,doc);JsonObject before=store.document(plan,"teacher");Map<String,String> disk=diskSnapshot();assertThrows(ExamException.class,()->bank.insert(plan,"token",Map.of("questionId","q-image","expectedRevision",1)));assertEquals(before,store.document(plan,"teacher"));assertEquals(disk,diskSnapshot());}
}
